// Workflow canary: exercises a user-facing flow with a real browser, not just a status
// code check -- this is the placeholder step sequence. Replace loadHomepage/verifyPageTitle
// with the customer's actual critical workflow (login, create a record, run a search,
// whatever most directly represents "the product works"). Screenshots on every step make
// a failure's cause visible in the Synthetics console without re-running anything.

const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');
const syntheticsConfiguration = synthetics.getConfiguration();

const runWorkflow = async function () {
    syntheticsConfiguration.setConfig({
        screenshotOnStepStart: true,
        screenshotOnStepSuccess: true,
        screenshotOnStepFailure: true,
    });

    const page = await synthetics.getPage();
    const targetUrl = process.env.TARGET_URL;

    await synthetics.executeStep('loadHomepage', async function () {
        const response = await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 30000 });
        if (!response) {
            throw new Error(`No response received loading ${targetUrl}`);
        }
        if (response.status() !== 200) {
            throw new Error(`Expected HTTP 200 loading ${targetUrl}, got ${response.status()}`);
        }
    });

    // TODO: replace with the customer's actual critical workflow.
    await synthetics.executeStep('verifyPageTitle', async function () {
        const title = await page.title();
        if (!title || title.length === 0) {
            throw new Error('Page loaded but returned an empty title');
        }
        log.info(`Page title: ${title}`);
    });
};

exports.handler = async () => {
    return await runWorkflow();
};
